import{z as l,x as s,o as e,c as p,q as i,j as t,D as a,d as B,s as r,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"恶性通胀的两个案例","description":"","frontmatter":{"title":"恶性通胀的两个案例","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mh-hyperinflations.md","filePath":"econ/mh-hyperinflations.md","lastUpdated":1791063341000}'),d={name:"econ/mh-hyperinflations.md"};function C(D,E,h,m,c,F){const n=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=i('<h1 id="恶性通胀的两个案例" tabindex="-1">恶性通胀的两个案例 <a class="header-anchor" href="#恶性通胀的两个案例" aria-label="Permalink to &quot;恶性通胀的两个案例&quot;">​</a></h1><div class="epigraph"><p>恶性通胀不是央行失手，是财政把印钞机当成唯一还开着的税基；终结它的从来不是货币技术，而是财政结算。</p><footer>—— 据 Cagan 1956；Sargent 1982 整理</footer></div><p><a href="/econ/mh-wartime-finance">上一课</a>写了通胀税的温和用法与「按旧平价复本」的信誉赎回；本课写同一台机器冲过税基收缩拐点的两个极端标本：1923 年的德国与 1946 年的匈牙利。理论工具已由<a href="/econ/seigniorage">通胀税与铸币税</a>备好，最优铸币税的框架见<a href="/econ/mt-optimal-inflation">最优通货膨胀</a>；本课只回答两个问题：加速为什么自我强化，结束为什么总是突然。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cagan 给恶性通胀下了操作性定义：月通胀率超过 50%。按这个门槛，二十世纪的极端样本远不止两例，但德国与匈牙利是量级上的两个端点。缺口不是记录惨状，而是解释一个悖论：印钞的人不是疯子，他们在弥补无法削减的赤字；可为什么越印收入反而越少、越印越不得不印——以及，为什么各国结束恶性通胀的方式惊人一致，几乎都发生在几周之内。</p><p><span class="marginnote">术语翻译：「操作性定义」就是把模糊说法换成可核验的数字——月通胀超过 50% 即恶性通胀。这个数有多猛：按复利，50% 的月通胀一年把物价推到年初的约 130 倍；而匈牙利 1946 年 7 月是 15 小时翻倍，一天约 3 倍，两周便是百万倍的量级。</span></p><h3 id="两个标本" tabindex="-1">两个标本 <a class="header-anchor" href="#两个标本" aria-label="Permalink to &quot;两个标本&quot;">​</a></h3><p>德国：战败赔款加国内战债，财政靠帝国银行贴现票据、垫付政府开支并购买外汇交赔款。1923 年 11 月，1 美元兑 4.2 万亿纸马克，月通胀约三万个百分点，币值约三天半翻倍。匈牙利：二战废墟、赔款与重建赤字，1946 年引入指数化的「税帕戈」也只是给记账单位续命；7 月峰值时币值约 15 小时翻倍，史上最大面额钞票印到 \\(10^{20}\\) 帕戈。</p><p><span class="marginnote">稳定后的德国货币量并没有立刻收缩，价格却停了——Sargent 用这一点论证稳定是「制度变迁」而非货币回收：财政停止透支、帝国银行拒绝再垫付政府，预期换了一个体制，钱就重新被愿意持有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把加速写成税基与税率的赛跑。实际铸币税 \\(s=\\frac{\\pi}{1+\\pi}\\cdot\\frac{M}{P}\\)：税率 \\(\\pi\\) 抬高，公众按 Cagan 需求 \\(m^d=k-\\alpha\\pi^{e}\\) 减持实际余额，税基 \\(M/P\\) 塌陷；财政缺口若不变，需要的名义印钞速度反而上升，\\(\\pi\\) 再抬高——螺旋没有内生的停点。预期是适应性的：公众的 \\(\\pi^{e}\\) 追上真实 \\(\\pi\\) 需要时间，滞后正是机器能转那么久的原因。</p><p><span class="marginnote">数字实例：给税基塌陷代个数——若公众愿持有的实际余额在月通胀 20% 时是月收入的 10%，到 50% 时只剩 3%，则通胀税在前者约为 \\(0.2/1.2\\times 0.10\\approx 1.7\\%\\)，在后者约为 \\(0.5/1.5\\times 0.03=1\\%\\)。税率翻倍多，实际收入反而更少：这就是失控段的拉弗顶点，螺旋没有停点。</span></p><p>两案结束的工序相同，且都与货币技术无关。德国 1923 年 11 月：停止对政府与商业票据的贴现、停止被动购买外汇，地租马克以土地与工业抵押为名限额发行；同月的紧急法令砍开支，1924 年道威斯计划重排赔款——财政结算与货币稳定同步落槌。匈牙利 1946 年 8 月：发行福林，1 福林兑 \\(4\\times 10^{29}\\) 帕戈，以金汇储备和当场平衡的预算背书。</p>',13)),(e(),t(o,null,{default:a(()=>[r(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E8%B4%A2%E6%94%BF%E7%BC%BA%E5%8F%A3%E6%97%A0%E6%B3%95%E5%89%8A%E5%87%8F%22%5D%20--%3E%20PRINT%5B%22%E5%8D%B0%E9%92%9E%E8%9E%8D%E8%B5%84%22%5D%0A%20%20PRINT%20--%3E%20PI%5B%22%E9%80%9A%E8%83%80%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20PI%20--%3E%20BASE%5B%22%E5%85%AC%E4%BC%97%E5%87%8F%E6%8C%81%E5%AE%9E%E9%99%85%E4%BD%99%E9%A2%9D%EF%BC%8C%E7%A8%8E%E5%9F%BA%E5%A1%8C%E9%99%B7%22%5D%0A%20%20BASE%20--%3E%20MORE%5B%22%E5%90%8C%E6%A0%B7%E7%BC%BA%E5%8F%A3%E9%9C%80%E8%A6%81%E5%8D%B0%E5%BE%97%E6%9B%B4%E5%BF%AB%22%5D%0A%20%20MORE%20--%3E%20PI%0A%20%20EXIT%7B%22%E8%B4%A2%E6%94%BF%E7%BB%93%E7%AE%97%E6%98%AF%E5%90%A6%E5%88%B0%E4%BD%8D%3F%22%7D%0A%20%20EXIT%20--%3E%7C%E5%90%A6%7C%20LOOP%5B%22%E8%9E%BA%E6%97%8B%E7%BB%A7%E7%BB%AD%E5%86%B2%E9%A1%B6%22%5D%0A%20%20EXIT%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E5%81%9C%E6%AD%A2%E5%AF%B9%E8%B4%A2%E6%94%BF%E9%80%8F%E6%94%AF%22%5D%0A%20%20STOP%20--%3E%20NEW%5B%22%E6%96%B0%E8%AE%B0%E8%B4%A6%E5%8D%95%E4%BD%8D%E9%99%90%E9%A2%9D%E5%8F%91%E8%A1%8C%22%5D%0A%20%20NEW%20--%3E%20STABLE%5B%22%E9%A2%84%E6%9C%9F%E6%8D%A2%E4%BD%93%E5%88%B6%EF%BC%8C%E4%BB%B7%E6%A0%BC%E5%81%9C%E4%BD%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"机制是悬崖式的预期切换：稳定成功与否不在发多少新钱，而在公众是否相信财政不再回来印。旧记账单位几乎救不回来——德国人早已改用美元与实物计价，匈牙利靠指数单位拖到换元；货币的单位是名分的锚，污染了就换。不这么做会错在哪：把稳定归功于抵押品或新钞票的印刷质量，就解释不了名义上「有抵押」的地租马克若没有财政停止透支照样一文不值；把恶性通胀归咎央行，就重复了上一课的误诊——财政主导在先，货币只是执行者。Bernholz 对数十个样本的对照给出同一结论：没有财政平衡的币制改革无一存活。",-1)),(e(),t(o,null,{default:a(()=>[r(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E4%BD%93%E5%88%B6%3A%20%E8%B4%A2%E6%94%BF%E9%9A%8F%E6%97%B6%E5%9B%9E%E6%9D%A5%E9%80%8F%E6%94%AF%22%5D%20--%3E%20FLEE%5B%22%E5%85%AC%E4%BC%97%E5%BC%83%E7%94%A8%E6%9C%AC%E5%B8%81%2C%20%E6%94%B9%E7%94%A8%E7%BE%8E%E5%85%83%E4%B8%8E%E5%AE%9E%E7%89%A9%22%5D%0A%20%20FLEE%20--%3E%20ZERO%5B%22%E6%9C%AC%E5%B8%81%E9%9C%80%E6%B1%82%E8%B6%8B%E9%9B%B6%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E4%BD%93%E5%88%B6%3A%20%E8%B4%A2%E6%94%BF%E5%81%9C%E6%AD%A2%E9%80%8F%E6%94%AF%22%5D%20--%3E%20TEST%7B%22%E5%85%AC%E4%BC%97%E8%AF%95%E6%8E%A2%3A%20%E8%BF%98%E5%9E%AB%E4%BB%98%E5%90%97%3F%22%7D%0A%20%20TEST%20--%3E%7C%22%E7%A1%AE%E8%AE%A4%E6%8B%92%E7%BB%9D%E5%9E%AB%E4%BB%98%22%7C%20TRUST%5B%22%E9%87%8D%E6%96%B0%E6%84%BF%E6%84%8F%E6%8C%81%E6%9C%89%E8%B4%A7%E5%B8%81%22%5D%0A%20%20TEST%20--%3E%7C%22%E7%BB%A7%E7%BB%AD%E9%80%8F%E6%94%AF%22%7C%20RELAPSE%5B%22%E5%B8%81%E6%94%B9%E5%A4%B1%E8%B4%A5%2C%20%E6%97%A7%E7%97%85%E5%A4%8D%E5%8F%91%22%5D%0A%20%20TRUST%20--%3E%20STABLE%5B%22%E6%97%A7%E9%92%9E%E4%B8%8D%E5%BF%85%E5%9B%9E%E6%94%B6%2C%20%E4%BB%B7%E6%A0%BC%E4%B9%9F%E5%81%9C%E4%BD%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">常见误区：初学者容易以为稳定靠的是新钞票或抵押品，实际上若财政没有同步停止透支，「有抵押」的地租马克照样一文不值；反过来，稳定后旧钞也不必立刻回收——德国的货币量稳定后并未收缩，价格照样停住。让人愿意重新持币的，是「政府不再回来印」这件事本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只走财政–货币轴：赔款政治、供给破坏与分配冲突都只作为赤字的来源出现，不展开；魏玛稳定后的岁月与福林时代的匈牙利也不在射程。恶性通胀中物价、工资与汇率的联动细节，以及「稳定后为何常伴随实际升值」，是<a href="/econ/inflation-anchoring">通胀预期锚定</a>与现代<a href="/econ/inflation-targeting">通胀目标制</a>的题材。央行独立性作为防止复发的制度遗产，见<a href="/econ/cb-independence-history">央行独立性简史</a>。</p><p>后课默认：货币崩溃是财政问题的影子，先看赤字，再看央行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>月通胀超过 50% 的恶性通胀，本质是通胀税冲过拉弗曲线顶点的失控段。</li><li>适应性预期的滞后让机器转得久；预期追上时，加速自我强化。</li><li>两个极端标本（德国 1923、匈牙利 1946）的结束工序相同：财政结算、停止透支、新单位限额发行。</li><li>稳定是制度变迁而非货币回收；没有财政平衡的币改无一存活。</li><li>出处：Cagan 1956；Sargent 1982；Bernholz 2003。</li></ul>',6))])}const _=l(d,[["render",C]]);export{T as __pageData,_ as default};
